import 'package:dartz/dartz.dart';import 'package:accounting_software/app/core/error/failures/failure.dart';import 'package:accounting_software/app/core/foundation/config/app_config.dart';import 'package:accounting_software/app/core/localization/translations/app_key.dart';import 'package:accounting_software/app/core/presentation/state_management/paged_list/paged_list_cubit.dart';import 'package:accounting_software/app/core/presentation/state_management/paged_list/paged_result.dart';import 'package:accounting_software/app/core/foundation/types/bulk_result.dart';import 'package:accounting_software/app/features/catalog/genders/domain/entity/gender.dart';import 'package:accounting_software/app/features/catalog/genders/domain/entity/gender_list_query.dart';import 'package:accounting_software/app/features/catalog/genders/domain/usecase/get_genders_use_case.dart';import 'package:accounting_software/app/features/catalog/genders/domain/usecase/delete_gender_use_case.dart';import 'package:accounting_software/app/features/catalog/genders/domain/usecase/set_gender_active_use_case.dart';import 'package:accounting_software/app/features/catalog/genders/presentation/cubit/genders_list/genders_list_effect.dart';import 'package:accounting_software/app/features/catalog/genders/presentation/localization/genders_keys.dart';class GendersListCubit extends PagedListCubit<Gender,GenderListQuery,GendersListEffect>{GendersListCubit({required GetGendersUseCase get,required SetGenderActiveUseCase setActive,required DeleteGenderUseCase delete,required super.flashMessages}):_get=get,_setActive=setActive,_delete=delete,super(initialQuery:const GenderListQuery(page:AppConfig.defaultPage,pageSize:AppConfig.defaultPageSize));final GetGendersUseCase _get;final SetGenderActiveUseCase _setActive;final DeleteGenderUseCase _delete;@override Future<Either<Failure,PagedResult<Gender>>> fetch(GenderListQuery q)=>_get(q);@override Future<Either<Failure,Unit>> deleteItem(Gender g)=>_delete(DeleteGenderParams(g.id));@override AppKey get deletedMessageKey=>GendersKeys.deleted;@override GendersListEffect buildMutationEffect(PagedMutationKind kind)=>const GendersMutatedEffect();Future<void> setStatus(GenderStatusFilter f)async{if(state.query.status==f)return;await applyQueryAndLoad(state.query.withStatus(f));}Future<void> setSorts(List<GenderSort> s)async{final q=state.query.withSorts(s);if(q==state.query)return;await applyQueryAndLoad(q);}Future<Either<Failure,Unit>> activate(int id)=>runMutation(()=>_setActive(SetGenderActiveParams(id:id,isActive:true)),kind:PagedMutationKind.statusChanged,successMessage:GendersKeys.statusUpdated,flashFailure:true,rowId:id);Future<Either<Failure,Unit>> deactivate(int id)=>runMutation(()=>_setActive(SetGenderActiveParams(id:id,isActive:false)),kind:PagedMutationKind.statusChanged,successMessage:GendersKeys.statusUpdated,flashFailure:true,rowId:id);Future<BulkResult<Gender>> bulkActivate(Iterable<Gender> items)=>runBulk(items:items,action:(g)=>_setActive(SetGenderActiveParams(id:g.id,isActive:true)),kind:PagedMutationKind.statusChanged,successMessage:GendersKeys.statusUpdated);Future<BulkResult<Gender>> bulkDeactivate(Iterable<Gender> items)=>runBulk(items:items,action:(g)=>_setActive(SetGenderActiveParams(id:g.id,isActive:false)),kind:PagedMutationKind.statusChanged,successMessage:GendersKeys.statusUpdated);Future<BulkResult<Gender>> bulkDelete(Iterable<Gender> items)=>runBulk(items:items,action:(g)=>_delete(DeleteGenderParams(g.id)),kind:PagedMutationKind.deleted,successMessage:GendersKeys.deleted);Future<void> onGenderSaved({required bool isNew})=>reloadAfterMutation(isNew?PagedMutationKind.created:PagedMutationKind.updated);}